}

contracts/Presale.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@uniswap/v2-periphery/contracts/interfaces/IUniswapV2Router02.sol";

contract Presale is Ownable, ReentrancyGuard {
    IERC20 public token;
    IUniswapV2Router02 public uniswapRouter;
    
    uint256 public softCap;
    uint256 public hardCap;
    uint256 public minContribution;
    uint256 public maxContribution;
    uint256 public presalePrice;
    uint256 public startTime;
    uint256 public endTime;
    uint256 public totalRaised;
    
    mapping(address => uint256) public contributions;
    bool public presaleFinalized;
    bool public liquidityAdded;

    event TokensPurchased(address indexed buyer, uint256 ethAmount, uint256 tokenAmount);
    event PresaleFinalized(uint256 totalRaised);
    event LiquidityAdded(uint256 ethAmount, uint256 tokenAmount);

    constructor(
        address _token,
        address _uniswapRouter,
        uint256 _softCap,
        uint256 _hardCap,
        uint256 _minContribution,
        uint256 _maxContribution,
        uint256 _presalePrice,
        uint256 _startTime,
        uint256 _duration
    ) {
        require(_token != address(0), "Invalid token address");
        require(_uniswapRouter != address(0), "Invalid router address");
        require(_softCap < _hardCap, "SoftCap must be less than HardCap");
        require(_minContribution < _maxContribution, "Min must be less than Max");
        
        token = IERC20(_token);
        uniswapRouter = IUniswapV2Router02(_uniswapRouter);
        softCap = _softCap;
        hardCap = _hardCap;
        minContribution = _minContribution;
        maxContribution = _maxContribution;
        presalePrice = _presalePrice;
        startTime = _startTime;
        endTime = _startTime + _duration;
    }

    function participate() external payable nonReentrant {
        require(block.timestamp >= startTime, "Presale not started");
        require(block.timestamp <= endTime, "Presale ended");
        require(!presaleFinalized, "Presale finalized");
        require(msg.value >= minContribution, "Below min contribution");
        require(msg.value <= maxContribution, "Exceeds max contribution");
        require(totalRaised + msg.value <= hardCap, "Hard cap reached");

        uint256 tokenAmount = (msg.value * presalePrice) / 1 ether;
        require(token.balanceOf(address(this)) >= tokenAmount, "Insufficient tokens");

        contributions[msg.sender] += msg.value;
        totalRaised += msg.value;

        emit TokensPurchased(msg.sender, msg.value, tokenAmount);
    }

    function finalize() external onlyOwner {
        require(block.timestamp > endTime || totalRaised >= hardCap, "Presale not ended");
        require(!presaleFinalized, "Already finalized");
        require(totalRaised >= softCap, "Soft cap not reached");

        presaleFinalized = true;
        
        // Add liquidity to Uniswap
        uint256 tokensForLiquidity = token.balanceOf(address(this)) / 2;
        uint256 ethForLiquidity = address(this).balance / 2;

        token.approve(address(uniswapRouter), tokensForLiquidity);
        
        uniswapRouter.addLiquidityETH{value: ethForLiquidity}(
            address(token),
            tokensForLiquidity,
            0,
            0,
            owner(),
            block.timestamp + 300
        );

        liquidityAdded = true;
        
        // Transfer remaining tokens and ETH to owner
        if (token.balanceOf(address(this)) > 0) {
            token.transfer(owner(), token.balanceOf(address(this)));
        }
        if (address(this).balance > 0) {
            payable(owner()).transfer(address(this).balance);
        }

        emit PresaleFinalized(totalRaised);
        emit LiquidityAdded(ethForLiquidity, tokensForLiquidity);
    }

    function refund() external nonReentrant {
        require(block.timestamp > endTime, "Presale not ended");
        require(totalRaised < softCap, "Soft cap reached");
        require(contributions[msg.sender] > 0, "No contribution");

        uint256 refundAmount = contributions[msg.sender];
        contributions[msg.sender] = 0;
        payable(msg.sender).transfer(refundAmount);
    }

    function withdrawTokens() external {
        require(presaleFinalized, "Presale not finalized");
        require(contributions[msg.sender] > 0, "No contribution");

        uint256 tokenAmount = (contributions[msg.sender] * presalePrice) / 1 ether;
        contributions[msg.sender] = 0;
        token.transfer(msg.sender, tokenAmount);
    }

    receive() external payable {}
}

contracts/Staking.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract Staking is ReentrancyGuard, Ownable {
    IERC20 public stakingToken;
    
    // Staking settings
    uint256 public rewardRate; // Rewards per second per token
    uint256 public minimumStakingPeriod; // Minimum time tokens must be staked
    uint256 public totalStaked;

    struct StakeInfo {
        uint256 amount;
        uint256 startTime;
        uint256 lastClaimTime;
        uint256 unclaimableRewards;
    }

    mapping(address => StakeInfo) public stakes;

    event Staked(address indexed user, uint256 amount);
    event Withdrawn(address indexed user, uint256 amount);
    event RewardsClaimed(address indexed user, uint256 reward);

    constructor(
        address _stakingToken,
        uint256 _rewardRate,
        uint256 _minimumStakingPeriod
    ) {
        require(_stakingToken != address(0), "Invalid token address");
        stakingToken = IERC20(_stakingToken);
        rewardRate = _rewardRate;
        minimumStakingPeriod = _minimumStakingPeriod;
    }

    function stake(uint256 _amount) external nonReentrant {
        require(_amount > 0, "Cannot stake 0");
        
        // Update rewards before modifying stake
        uint256 pendingReward = calculateRewards(msg.sender);
        stakes[msg.sender].unclaimableRewards += pendingReward;
        
        // Transfer tokens to contract
        require(stakingToken.transferFrom(msg.sender, address(this), _amount), "Transfer failed");
        
        // Update stake info
        if (stakes[msg.sender].amount == 0) {
            stakes[msg.sender].startTime = block.timestamp;
            stakes[msg.sender].lastClaimTime = block.timestamp;
        }
        
        stakes[msg.sender].amount += _amount;
        totalStaked += _amount;
        
        emit Staked(msg.sender, _amount);
    }

    function withdraw(uint256 _amount) external nonReentrant {
        require(_amount > 0 && _amount <= stakes[msg.sender].amount, "Invalid amount");
        require(
            block.timestamp >= stakes[msg.sender].startTime + minimumStakingPeriod,
            "Minimum staking period not met"
        );
        
        // Update rewards before modifying stake
        uint256 pendingReward = calculateRewards(msg.sender);
        stakes[msg.sender].unclaimableRewards += pendingReward;
        
        // Update stake info
        stakes[msg.sender].amount -= _amount;
        totalStaked -= _amount;
        
        // Transfer tokens back to user
        require(stakingToken.transfer(msg.sender, _amount), "Transfer failed");
        
        emit Withdrawn(msg.sender, _amount);
    }

    function claimRewards() external nonReentrant {
        uint256 rewards = calculateRewards(msg.sender) + stakes[msg.sender].unclaimableRewards;
        require(rewards > 0, "No rewards to claim");
        
        stakes[msg.sender].lastClaimTime = block.timestamp;
        stakes[msg.sender].unclaimableRewards = 0;
        
        require(stakingToken.transfer(msg.sender, rewards), "Reward transfer failed");
        
        emit RewardsClaimed(msg.sender, rewards);
    }

    function calculateRewards(address _staker) public view returns (uint256) {
        if (stakes[_staker].amount == 0) {
            return 0;
        }

        uint256 timeElapsed = block.timestamp - stakes[_staker].lastClaimTime;
        return (stakes[_staker].amount * timeElapsed * rewardRate) / 1e18;
    }

    // Admin functions
    function updateRewardRate(uint256 _newRate) external onlyOwner {
        rewardRate = _newRate;
    }

    function updateMinimumStakingPeriod(uint256 _newPeriod) external onlyOwner {
        minimumStakingPeriod = _newPeriod;
    }

    // View functions
    function getStakeInfo(address _staker) external view returns (
        uint256 amount,
        uint256 startTime,
        uint256 pendingRewards
    ) {
        StakeInfo memory stake = stakes[_staker];
        return (
            stake.amount,
            stake.startTime,
            calculateRewards(_staker) + stake.unclaimableRewards
        );
    }
}

contracts/Token.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract Token is ERC20, Ownable {
    constructor(
        string memory name,
        string memory symbol,
        uint256 initialSupply
    ) ERC20(name, symbol) {
        _mint(msg.sender, initialSupply * 10 ** decimals());
    }

    function mint(address to, uint256 amount) public onlyOwner {
        _mint(to, amount);
    }

    function burn(uint256 amount) public {
        _burn(msg.sender, amount);
    }
}

